import urllib.request
import urllib.error
import time

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"
        for attempt in range(3):
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if attempt < 2:
                        time.sleep(0.5 * (2 ** attempt))
                        continue
                    else:
                        raise RateLimitError("Rate limit exceeded after 3 attempts")
                elif 500 <= e.code < 600:
                    if attempt < 1:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error {e.code} after 1 retry")
                else:
                    raise ClientError(f"Client error {e.code}")
            except urllib.error.URLError:
                if attempt < 1:
                    time.sleep(1)
                    continue
                else:
                    raise ConnectionError("Failed to connect after 1 retry")
        return None  # This line should never be reached due to exception handling

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass
